"""Original solid-tumor questions: lung and initial breast-cancer characterization."""
from qbank_authoring import question,ref
rows=[]
LU=ref('NCI professional NSCLC summary','https://www.cancer.gov/types/lung/hp/non-small-cell-lung-treatment-pdq')
SL=ref('NCI professional SCLC summary','https://www.cancer.gov/types/lung/hp/small-cell-lung-treatment-pdq')
BR=ref('NCI professional breast cancer summary','https://www.cancer.gov/types/breast/hp/breast-treatment-pdq')
MO=ref('ASCO NSCLC driver-alteration living guideline: 2026 update','https://doi.org/10.1200/JCO-26-01958')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('A never-smoker has a peripheral lung adenocarcinoma. Which treatment-planning principle is most appropriate?', 'Obtain comprehensive relevant molecular and immunophenotypic biomarkers rather than using smoking history to select treatment alone',[
 ('Never-smokers cannot develop primary lung cancer','Adenocarcinoma commonly occurs in this setting.'),('Smoking history alone identifies the exact driver mutation','It changes probabilities but does not replace testing.'),('High PD-L1 makes every driver test unnecessary','Molecular drivers can determine a different preferred strategy.')],
 'Clinical phenotype guides suspicion, not the final molecular answer','**Actionable alterations occur across clinical groups.**',['Adenocarcinoma is an important setting for broad testing.','Preserve adequate tissue and consider complementary plasma testing when appropriate.'],'**Use validated biomarkers before a definitive systemic plan when feasible.**',['Do not assume one mutation from sex, age or smoking alone.','Integrate stage, fitness and patient goals.'],[['Histology','Adenocarcinoma'],['Phenotype','Changes prior probability'],['Treatment','Requires actual biomarkers']],[LU,MO],style='clinical_scenario')

q('A central cavitating lung tumor has squamous differentiation and PTHrP-mediated hypercalcemia. Which histology best fits?', 'Squamous cell carcinoma',[
 ('Typical carcinoid','This has a different neuroendocrine morphology/behavior.'),('Small-cell carcinoma','This is a high-grade neuroendocrine cancer with different common paraneoplastic patterns.'),('Adenocarcinoma established solely by any lung mass','The stated differentiation specifically supports squamous histology.')],
 'Pathology anchors an otherwise suggestive clinical pattern','**Central cavitation and humoral hypercalcemia are compatible associations.**',['Neither feature alone is histologically definitive.','Mixed or unusual tumors require pathological classification.'],'**Treat calcium urgently and stage the cancer.**',['Do not substitute paraneoplastic clues for tissue.','Assess molecular testing according to current disease guidance rather than old phenotype assumptions.'],[['Morphology','Squamous differentiation'],['Possible association','PTHrP hypercalcemia'],['Plan','Tissue-based staging/treatment']],[LU],style='clinical_scenario')

q('Biopsy shows small malignant cells with scant cytoplasm, nuclear molding, high proliferation and neuroendocrine-marker expression. Which diagnosis is most likely in a compatible lung mass?', 'Small-cell lung carcinoma',[
 ('A typical pulmonary carcinoid','This is usually better differentiated and lower grade.'),('A well-differentiated squamous carcinoma','The morphology and neuroendocrine pattern differ.'),('A benign granuloma','The stated cytology is malignant.')],
 'Neuroendocrine lineage and grade both matter','**SCLC is an aggressive high-grade neuroendocrine carcinoma.**',['Rapid dissemination makes systemic staging important.','Markers require interpretation with morphology.'],'**Assess extent and urgent complications.**',['Brain imaging is relevant to staging.','Do not manage it as a localized benign neuroendocrine lesion.'],[['Lineage','Neuroendocrine'],['Grade','High'],['Clinical behavior','Rapid growth/dissemination']],[SL],style='clinical_scenario')

q('A smoker has repeated pneumonia in the same lobe and persistent lobar collapse after treatment. Which next concern is important?', 'An obstructing endobronchial lesion requiring appropriate imaging and airway evaluation',[
 ('Recurrent infection proves there can be no tumor','Obstruction can predispose to postobstructive infection.'),('Resolution of fever makes the persistent collapse irrelevant','An anatomical cause can remain.'),('A normal serum tumor-marker panel excludes lung cancer','No such panel reliably excludes it.')],
 'A recurring anatomical pattern suggests a local cause','**Treating infection may not relieve an underlying obstruction.**',['Tumor, foreign body and benign stenosis are possibilities.','Hemoptysis and constitutional symptoms add concern.'],'**Use CT and bronchoscopy when indicated.**',['Obtain tissue safely and manage infection concurrently.','Do not rely on repeated empirical antibiotics alone.'],[['Pattern','Same-lobe recurrence'],['Mechanism','Possible obstruction'],['Evaluation','Anatomy and tissue']],[LU],style='clinical_scenario')

q('An apical lung tumor causes shoulder pain radiating along the medial arm, hand weakness and ipsilateral ptosis with miosis. Which local invasion pattern is suggested?', 'Superior sulcus involvement of lower brachial plexus and sympathetic pathways',[
 ('An isolated recurrent-laryngeal lesion as the complete explanation','That mainly causes voice change and does not explain the whole pattern.'),('A purely diaphragmatic phrenic lesion','This does not explain the lower-plexus and Horner findings.'),('A pituitary endocrine syndrome','The symptoms localize to thoracic-inlet structures.')],
 'Anatomy can identify the threatened structures','**A superior sulcus tumor can invade neural structures near the apex.**',['The Pancoast pattern does not specify histology by itself.','Local staging determines resectability and multimodality planning.'],'**Obtain tissue and detailed thoracic-inlet staging.**',['Assess vascular and vertebral involvement.','Treat pain and functional deficits while planning definitive care.'],[['Pain/hand weakness','Lower plexus'],['Horner features','Sympathetic pathway'],['Site','Superior sulcus']],[LU],style='clinical_scenario')

q('Potentially resectable NSCLC has PET-avid mediastinal nodes. Which staging principle is most appropriate when nodal status changes treatment?', 'Obtain appropriate pathological nodal assessment, often with EBUS/EUS-guided sampling',[
 ('PET avidity alone proves nodal metastasis in every case','Inflammation can cause false-positive uptake.'),('Ignore mediastinal nodes because only the primary tumor size matters','Nodal status can alter treatment strategy.'),('A negative serum marker replaces nodal staging','It does not answer the anatomical question.')],
 'A management-changing imaging finding may need confirmation','**Mediastinal staging avoids both under- and overtreatment.**',['Sampling approach depends on node station and local expertise.','A negative procedure may need further assessment if suspicion remains high.'],'**Use a multidisciplinary staging pathway.**',['Preserve adequate material for diagnosis and biomarkers.','Interpret sample adequacy rather than treating every negative as definitive.'],[['PET','Suspicion'],['Sampling','Pathological confirmation'],['Decision','Resectability/multimodality plan']],[LU],style='clinical_scenario')

q('Metastatic NSCLC has high PD-L1 expression but molecular testing is pending. Which principle is correct?', 'PD-L1 alone should not replace comprehensive driver assessment when selecting initial systemic treatment',[
 ('High PD-L1 excludes EGFR or other actionable drivers','These findings can coexist.'),('Any high PD-L1 result makes all targeted treatment ineffective','It does not establish that.'),('Biomarker testing is relevant only after all treatments fail','It can determine the initial strategy.')],
 'Different biomarkers answer different treatment questions','**A targetable driver can change the preferred sequence and expected benefit.**',['Use validated tissue and/or plasma testing as appropriate.','Clinical urgency may require a tailored interim plan.'],'**Coordinate rapid complete testing with the treating team.**',['Avoid a reflex single-marker decision.','Assess assay quality and current therapy evidence.'],[['PD-L1','Immunotherapy-related information'],['Driver tests','Targeted-treatment information'],['Selection','Integrated biomarkers']],[MO],style='clinical_scenario')

q('What is the practical distinction in the limited-versus-extensive SCLC classification?', 'Limited disease can be encompassed in an appropriate tolerable thoracic radiation plan, whereas distant spread or broader extent indicates extensive disease',[
 ('Any regional node automatically means extensive disease','Some regional nodal disease remains within limited-stage definitions.'),('Limited disease means a benign low-grade neuroendocrine tumor','SCLC remains high-grade malignant disease.'),('The distinction replaces all TNM and imaging information','Detailed staging still informs treatment.')],
 'A treatment-oriented extent category complements anatomical staging','**The radiation-encompassment concept is central to the traditional distinction.**',['Malignant effusions and distant metastases generally indicate extensive disease.','Borderline thoracic patterns require specialist planning.'],'**Complete appropriate systemic and brain staging.**',['Do not infer the category from primary size alone.','Use current stage-specific treatment evidence.'],[['Limited','Tolerable thoracic treatment volume'],['Extensive','Beyond that extent/distant spread'],['Assessment','Full imaging and clinical context']],[SL])

q('Which routine breast-cancer biomarkers directly define major systemic-treatment pathways?', 'Estrogen receptor, progesterone receptor and HER2 status',[
 ('Serum CEA alone','It does not replace tissue receptor characterization.'),('Tumor diameter alone without receptor testing','Size informs stage but not all biological treatment options.'),('A CBC as a substitute for tumor biomarkers','It assesses the patient rather than tumor receptor biology.')],
 'Biological subtype and anatomical stage are complementary','**Hormone-receptor and HER2 findings guide endocrine and HER2-directed options.**',['Assays and interpretation must follow validated standards.','Other genomic or immune biomarkers can matter in defined settings.'],'**Integrate subtype with stage, menopausal status and risk.**',['A receptor label does not specify one universal regimen.','Reassess relevant metastatic tissue when indicated.'],[['ER/PR','Endocrine pathway'],['HER2','HER2-directed pathway'],['Stage/risk','Treatment context']],[BR])

q('A rapidly enlarged erythematous breast has peau d’orange and diffuse skin involvement despite antibiotics. Which diagnosis requires urgent assessment?', 'Inflammatory breast cancer',[
 ('Routine mastitis as the only possible cause','Persistent diffuse changes require cancer assessment.'),('A benign fibroadenoma as the typical explanation','A discrete benign mass does not explain this pattern.'),('An isolated superficial allergy as established by redness alone','The progressive breast/skin syndrome needs tissue and imaging.')],
 'Dermal lymphatic obstruction can mimic inflammation','**Inflammatory breast cancer is a clinical-pathological syndrome requiring prompt workup.**',['A discrete mass may be absent.','Skin findings alone do not determine receptor subtype.'],'**Use urgent breast imaging and biopsy.**',['Do not continue repeated empirical antibiotics without reassessment.','Stage and characterize the tumor for multimodality care.'],[['Skin','Edema/peau d’orange'],['Course','Rapid diffuse progression'],['Action','Urgent cancer assessment']],[BR],style='clinical_scenario')
